// trailWebUrl builds the canonical browser URL for a trail so API clients (the
// CLI, integrations) can surface a real link without reconstructing the route
// themselves — keeping them from drifting out of sync when the route changes.
// owner/repo come from the persisted repo identity (not the client-supplied
// path casing); host is the validated path param (VALID_HOSTS), so its casing
// is already canonical. Segments are URL-encoded via the shared buildTrailUrl.
// The decorative title slug is omitted; the detail page canonicalizes the URL
// to add it when visited.
function trailWebUrl(c: TrailContext, repo: Repo, number: number): string {
  return buildTrailUrl(c.env.FRONTEND_BASE_URL, c.req.param("host") ?? "", repo.full_name, number)
}

